/**
 * Wave-2 agent drafts for frm/tax/coso/crma/iia (fa already above floor).
 * Appends to existing bank modules then re-emits.
 * Run: node scripts/lib/agent-banks/_write-banks-wave2.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { pathToFileURL } from "node:url";

const DIR = dirname(fileURLToPath(import.meta.url));

function t(title, topic, definition, example, trap, formula) {
  return formula
    ? [title, topic, definition, example, trap, formula]
    : [title, topic, definition, example, trap];
}

function expand(specs) {
  return specs.map(([title, topic, mech, example, trap, formula]) =>
    t(title, topic, `${title} ${mech}`, example, trap, formula),
  );
}

async function loadExisting(name, exportName) {
  const mod = await import(pathToFileURL(join(DIR, `${name}.mjs`)).href);
  return mod[exportName] || [];
}

function emit(name, exportName, drafts) {
  writeFileSync(
    join(DIR, `${name}.mjs`),
    `/** Agent-authored ${name} encyclopedia drafts — workplace only. */\nexport const ${exportName} = ${JSON.stringify(drafts, null, 2)};\n`,
    "utf8",
  );
  console.log(name, drafts.length);
}

