function dedupe(drafts) {
  const seen = new Set();
  const out = [];
  for (const d of drafts) {
    const key = String(d[0] || "").toLowerCase().trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(d);
  }
  return out;
}

